import { Injectable, CanActivate, ExecutionContext, HttpException, HttpStatus } from '@nestjs/common';
import Redis from 'ioredis';

const WINDOW_MS = 60_000;
const MAX_REQUESTS = 100;

@Injectable()
export class RateLimiterService {
  constructor(private readonly redis: Redis) {}

  /**
   * Returns true if the request identified by `identifier` is allowed
   * under the configured sliding-window limit, false otherwise.
   */
  async checkLimit(identifier: string): Promise<boolean> {
    const key = `rate:${identifier}`;
    const now = Date.now();

    // Round trip #1: pull the entire stored timestamp list back to the app.
    const raw = await this.redis.lrange(key, 0, -1);

    // Trim the window in application memory, not in Redis.
    const timestamps = raw
      .map((entry) => Number(entry))
      .filter((ts) => ts > now - WINDOW_MS);

    // Check-then-write: not atomic with the read above.
    if (timestamps.length >= MAX_REQUESTS) {
      return false;
    }

    timestamps.push(now);

    // Round trips #2 and #3: rewrite the whole trimmed list back to Redis.
    await this.redis.del(key);
    if (timestamps.length > 0) {
      await this.redis.rpush(key, ...timestamps.map(String));
    }

    // Round trip #4: refresh the TTL so idle keys eventually disappear.
    await this.redis.expire(key, Math.ceil(WINDOW_MS / 1000));

    return true;
  }
}

@Injectable()
export class RateLimiterGuard implements CanActivate {
  constructor(private readonly rateLimiter: RateLimiterService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const identifier = request.user?.id ?? request.ip;

    const allowed = await this.rateLimiter.checkLimit(identifier);
    if (!allowed) {
      throw new HttpException('Too many requests', HttpStatus.TOO_MANY_REQUESTS);
    }
    return true;
  }
}
